import type { DecisionAction } from '@refy-design/web';
import { DecisionActions } from '@refy-design/web';
import type { PropertyActionGroupState } from '@refy-design/web';
import { useEffect } from 'react';
import { useRef } from 'react';
import { useState } from 'react';
function FunctionalActions() {
  const [active, setActive] = useState<DecisionAction>();
  const [state, setState] = useState<PropertyActionGroupState>('idle');
  const timers = useRef<number[]>([]);
  useEffect(() => () => timers.current.forEach(window.clearTimeout), []);
  function act(action: DecisionAction) {
    setActive(action);
    setState('processing');
    timers.current.forEach(window.clearTimeout);
    timers.current = [
      window.setTimeout(() => setState('completed'), 700),
      window.setTimeout(() => {
        setState('idle');
        setActive(undefined);
      }, 1800),
    ];
  }
  return <DecisionActions activeAction={active} state={state} onAction={act} />;
}
export function Example() {
  return <FunctionalActions />;
}

